const MOD:i64=998_244_353; const CAP:usize=4096; const Q:usize=16;
#[derive(Clone,Copy)] struct Node{sum:i64,mul:i64,add:i64,left:i32,right:i32}
impl Default for Node{fn default()->Self{Self{sum:0,mul:1,add:0,left:-1,right:-1}}}
struct Tree{a:[Node;CAP],used:usize}
impl Tree{
 fn norm(x:i64)->i64{x.rem_euclid(MOD)}
 fn clone(&mut self,s:i32)->i32{if s<0||self.used==CAP{return -1}let d=self.used as i32;self.a[self.used]=self.a[s as usize];self.used+=1;d}
 fn make(&mut self,sum:i64,l:i32,r:i32)->i32{if self.used==CAP{return -1}let d=self.used as i32;self.a[self.used]=Node{sum,mul:1,add:0,left:l,right:r};self.used+=1;d}
 fn apply(&mut self,x:i32,m:i64,b:i64,len:usize){let m=Self::norm(m);let b=Self::norm(b);let n=&mut self.a[x as usize];n.sum=Self::norm(m*n.sum+b*len as i64);n.mul=Self::norm(m*n.mul);n.add=Self::norm(m*n.add+b);}
 fn push(&mut self,x:i32,l:usize,r:usize)->bool{let m=self.a[x as usize].mul;let b=self.a[x as usize].add;if m==1&&b==0{return true}if l<r{let mid=l+(r-l)/2;let lc=self.clone(self.a[x as usize].left);let rc=self.clone(self.a[x as usize].right);if lc<0||rc<0{return false}self.a[x as usize].left=lc;self.a[x as usize].right=rc;self.apply(lc,m,b,mid-l+1);self.apply(rc,m,b,r-mid);}self.a[x as usize].mul=1;self.a[x as usize].add=0;true}
 fn build(&mut self,v:&[i64],l:usize,r:usize)->i32{if l==r{return self.make(v[l],-1,-1)}let mid=l+(r-l)/2;let x=self.build(v,l,mid);let y=self.build(v,mid+1,r);if x<0||y<0{return -1}self.make(Self::norm(self.a[x as usize].sum+self.a[y as usize].sum),x,y)}
 fn update(&mut self,root:i32,l:usize,r:usize,ql:usize,qr:usize,m:i64,b:i64)->i32{if ql<=l&&r<=qr{let x=self.clone(root);if x<0{return -1}self.apply(x,m,b,r-l+1);return x}let x=self.clone(root);if x<0||!self.push(x,l,r){return -1}let mid=l+(r-l)/2;if ql<=mid{let child=self.a[x as usize].left;let y=self.update(child,l,mid,ql,qr,m,b);if y<0{return -1}self.a[x as usize].left=y}if qr>mid{let child=self.a[x as usize].right;let y=self.update(child,mid+1,r,ql,qr,m,b);if y<0{return -1}self.a[x as usize].right=y}let z=Self::norm(self.a[self.a[x as usize].left as usize].sum+self.a[self.a[x as usize].right as usize].sum);self.a[x as usize].sum=z;x}
 fn logical_child(&mut self,s:i32,right:bool,l:usize,r:usize)->i32{let child=if right{self.a[s as usize].right}else{self.a[s as usize].left};let c=self.clone(child);if c<0{return -1}let m=self.a[s as usize].mul;let b=self.a[s as usize].add;if m!=1||b!=0{let mid=l+(r-l)/2;self.apply(c,m,b,if right{r-mid}else{mid-l+1});}c}
 fn copy_range(&mut self,dst:i32,src:i32,l:usize,r:usize,ql:usize,qr:usize)->i32{if ql<=l&&r<=qr{return src}let x=self.clone(dst);if x<0||!self.push(x,l,r){return -1}let mid=l+(r-l)/2;if ql<=mid{let s=self.logical_child(src,false,l,r);if s<0{return -1}let d=self.a[x as usize].left;let y=self.copy_range(d,s,l,mid,ql,qr);if y<0{return -1}self.a[x as usize].left=y}if qr>mid{let s=self.logical_child(src,true,l,r);if s<0{return -1}let d=self.a[x as usize].right;let y=self.copy_range(d,s,mid+1,r,ql,qr);if y<0{return -1}self.a[x as usize].right=y}let z=Self::norm(self.a[self.a[x as usize].left as usize].sum+self.a[self.a[x as usize].right as usize].sum);self.a[x as usize].sum=z;x}
 fn query(&self,x:i32,l:usize,r:usize,ql:usize,qr:usize,cm:i64,ca:i64)->i64{if ql<=l&&r<=qr{return Self::norm(cm*self.a[x as usize].sum+ca*(r-l+1) as i64)}let mid=l+(r-l)/2;let nm=Self::norm(cm*self.a[x as usize].mul);let na=Self::norm(cm*self.a[x as usize].add+ca);let mut z=0;if ql<=mid{z=self.query(self.a[x as usize].left,l,mid,ql,qr,nm,na)}if qr>mid{z=Self::norm(z+self.query(self.a[x as usize].right,mid+1,r,ql,qr,nm,na))}z}
}
unsafe fn put(out:*mut u8,at:usize,x:i64){let b=x as u64;for j in 0..8{*out.add(at+j)=(b>>(8*j)) as u8;}}
unsafe fn read(p:*const i64,i:usize)->i64{*p.add(i)}
unsafe fn valid_ref(k:i64,i:usize,kinds:&[i64;Q])->bool{k==-1||(k>=0&&(k as usize)<i&&(kinds[k as usize]==0||kinds[k as usize]==1))}
#[no_mangle] pub unsafe extern "C" fn persistent_range_affine_range_sum(input:*const i64,length:usize,output:*mut u8,capacity:usize)->i64{
 if input.is_null()||length<2||length>115{return -1}let n0=read(input,0);let q0=read(input,1);if n0<1||n0>16||q0<1||q0>16{return -1}let n=n0 as usize;let q=q0 as usize;let mut off=2+n;if length<off{return -1}let mut vals=[0i64;16];for j in 0..n{vals[j]=read(input,2+j);if vals[j]<0||vals[j]>=MOD{return -1}}
 let mut kind=[0i64;Q];let mut refs=[0i64;Q];let mut src=[0i64;Q];let mut ls=[0i64;Q];let mut rs=[0i64;Q];let mut ms=[1i64;Q];let mut bs=[0i64;Q];
 for i in 0..q{if off>=length{return -1}let op=read(input,off);let w=if op==0{6}else if op==1{5}else if op==2{4}else{return -1};if length-off<w{return -1}let k=read(input,off+1);if !valid_ref(k,i,&kind){return -1}kind[i]=op;refs[i]=k;if op==0||op==2{ls[i]=read(input,off+2);rs[i]=read(input,off+3);if ls[i]<0||rs[i]<=ls[i]||rs[i]>n0{return -1}}if op==0{ms[i]=read(input,off+4);bs[i]=read(input,off+5);if ms[i]<1||ms[i]>=MOD||bs[i]<0||bs[i]>=MOD{return -1}}if op==1{src[i]=read(input,off+2);ls[i]=read(input,off+3);rs[i]=read(input,off+4);if !valid_ref(src[i],i,&kind)||ls[i]<0||rs[i]<=ls[i]||rs[i]>n0{return -1}}off+=w;}
 if off!=length{return -1}let mut t=Tree{a:[Node::default();CAP],used:0};let initial=t.build(&vals[..n],0,n-1);if initial<0{return -1}let mut roots=[0i32;Q];let mut ans=[0i64;Q];let mut na=0;
 for i in 0..q{let base=if refs[i]<0{initial}else{roots[refs[i] as usize]};if kind[i]==0{roots[i]=t.update(base,0,n-1,ls[i] as usize,rs[i] as usize-1,ms[i],bs[i]);if roots[i]<0{return -1}}else if kind[i]==1{let s=if src[i]<0{initial}else{roots[src[i] as usize]};roots[i]=t.copy_range(base,s,0,n-1,ls[i] as usize,rs[i] as usize-1);if roots[i]<0{return -1}}else{ans[na]=t.query(base,0,n-1,ls[i] as usize,rs[i] as usize-1,1,0);na+=1}}
 let bytes=8*na;if output.is_null()||capacity<bytes{return -2}for i in 0..na{put(output,8*i,ans[i])}bytes as i64
}
